{
  "name": "@yyg27/manbun",
  "version": "4.10.0",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "manbun", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/yyg27"
  },
  "homepage": "https://github.com/yyg27/manbun",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yyg27/manbun.git"
  },
  "bugs": {
    "url": "https://github.com/yyg27/manbun/issues"
  },
  "main": "./.opencode/plugins/manbun.mjs",
  "exports": {
    ".": "./.opencode/plugins/manbun.mjs",
    "./plugin": "./.opencode/plugins/manbun.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "scripts/uninstall.js",
    "scripts/cursor-hooks.js",
    "assets/",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension && npm test --prefix manbun-mcp"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}

{
  "name": "manbun-pi-extension-dev",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test ./test/*.test.js"
  }
}
